script = r'''
import openpyxl, re, sys
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
errors=[]
if wb.sheetnames != ['Task','Data']:
    errors.append(f'Sheet names changed: {wb.sheetnames}')
ws=wb['Task']
# Ranges to verify all formula strings.
coords=[]
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            coords.append((r,c))
for r,c in coords:
    v=ws.cell(r,c).value
    if not (isinstance(v,str) and v.startswith('=')):
        errors.append(f'{ws.cell(r,c).coordinate} is not formula: {v!r}')

# Exact formula expectations.
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
        if ws.cell(r,c).value != expected:
            errors.append(f'{col}{r} expected {expected}, got {ws.cell(r,c).value}')
for offset,r in enumerate(range(35,41)):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=({col}{12+offset}-{col}{19+offset})/{col}{26+offset}*100'
        if ws.cell(r,c).value != expected:
            errors.append(f'{col}{r} expected {expected}, got {ws.cell(r,c).value}')
expected_summary = {
    42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE',46:'PERCENTILE25',47:'PERCENTILE75'
}
for c in range(8,13):
    col=get_column_letter(c)
    expected = {
        42:f'=MIN({col}35:{col}40)',
        43:f'=MAX({col}35:{col}40)',
        44:f'=MEDIAN({col}35:{col}40)',
        45:f'=AVERAGE({col}35:{col}40)',
        46:f'=PERCENTILE({col}35:{col}40,0.25)',
        47:f'=PERCENTILE({col}35:{col}40,0.75)',
        50:f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)',
    }
    for r, exp in expected.items():
        if ws.cell(r,c).value != exp:
            errors.append(f'{col}{r} expected {exp}, got {ws.cell(r,c).value}')

print('Verification: workbook re-opened with data_only=False')
print('Sheet names:', wb.sheetnames)
print('Formula cell count checked:', len(coords))
print('All formula cells start with =:', not any('is not formula' in e for e in errors))
print('Lookup formula sample H12:', ws['H12'].value)
print('Lookup formula sample L31:', ws['L31'].value)
print('Net SLA sample H35:', ws['H35'].value)
print('Net SLA sample L40:', ws['L40'].value)
print('Summary samples H42:H47:')
for r in range(42,48): print(f'  H{r}: {ws.cell(r,8).value}')
print('Weighted mean sample H50:', ws['H50'].value)
print('Weighted mean sample L50:', ws['L50'].value)
if errors:
    print('ERRORS:')
    for e in errors[:50]: print(e)
    sys.exit(1)
print('Verification passed')
'''
res=terminal('python3 - <<\'PY\'\n'+script+'\nPY', timeout=120, workdir='/root')
print(res['output'])
if res['exit_code'] != 0: print('EXIT', res['exit_code'])"}
